mapper.select:
SELECT es.schedule_id,rr.status request_status
FROM repair_request rr
JOIN engineer_skill sk ON sk.fault_type_id=rr.fault_type_id AND sk.engineer_id=#{engineerId}
JOIN engineer_service_area ea ON ea.service_area_id=rr.service_area_id AND ea.engineer_id=#{engineerId}
JOIN engineer_profile ep ON ep.engineer_id=#{engineerId}
JOIN system_user u ON u.user_id=ep.engineer_id
JOIN engineer_schedule es ON es.schedule_id=#{scheduleId} AND es.engineer_id=#{engineerId}
WHERE rr.repair_request_id=#{requestId} AND rr.customer_id=#{customerId} AND rr.customer_id<>ep.engineer_id
AND rr.status IN ('OPEN','BOOKED') AND es.status='AVAILABLE' AND es.service_date>=CURRENT_DATE
AND ep.qualification_status='APPROVED' AND ep.employment_status='ACTIVE' AND u.status='ACTIVE'
